//! Traits for operations of dialects defined at runtime.
//!
//! A dialect loaded from IRDL is an *extensible* dialect: its operations are `DynamicOpDefinition`s, created at runtime rather than generated by ODS.
//! In C++, ODS lets an operation list traits such as `Terminator` and set `hasVerifier = 1`.
//! For dynamic operations, MLIR lets us attach the same behavior after the dialect has been loaded.

use std::ffi::c_void;

use melior::{
    Context,
    ir::{OperationRef, operation::OperationLike, r#type::TypeId},
};
use mlir_sys::{
    MlirDynamicOpTrait, MlirDynamicOpTraitCallbacks, MlirLogicalResult, MlirOperation,
    mlirContextGetOrLoadDialect, mlirDialectIsAExtensibleDialect, mlirDynamicOpTraitAttach,
    mlirDynamicOpTraitCreate, mlirDynamicOpTraitIsTerminatorCreate,
};

use crate::{
    diagnostic::emit_error,
    error::{Error, VerificationError},
    string::string_ref,
};

/// The address of this static is the `TypeID` of verifier traits.
///
/// An operation can hold at most one trait per `TypeID`, so this allows one custom verifier per operation.
/// `TypeID`s must be 8-byte aligned, which a `u64` is.
static VERIFIER_TRAIT_ID: u64 = 0;

const SUCCESS: MlirLogicalResult = MlirLogicalResult { value: 1 };
const FAILURE: MlirLogicalResult = MlirLogicalResult { value: 0 };

/// Marks the dynamic operation `op_name` as a block terminator.
///
/// This is the runtime equivalent of listing the `Terminator` trait in ODS.
pub fn attach_terminator(context: &Context, op_name: &str) -> Result<(), Error> {
    ensure_dynamic_operation(context, op_name)?;

    // SAFETY: The trait is freshly allocated and `mlirDynamicOpTraitAttach`
    // takes ownership of it. The operation is a registered dynamic operation,
    // which `mlirDynamicOpTraitAttach` requires.
    let trait_ = unsafe { mlirDynamicOpTraitIsTerminatorCreate() };
    attach(context, op_name, trait_)
}

/// Attaches a custom verifier to the dynamic operation `op_name`.
///
/// This is the runtime equivalent of `hasVerifier = 1` in ODS.
/// MLIR calls `verifier` whenever an operation named `op_name` is verified, *before* the IRDL constraints (operand, result, and attribute kinds) are checked.
/// When it returns an error, its message is reported at the operation's location the way `Operation::emitOpError` does: prefixed with `'<op name>' op`.
pub fn attach_verifier<F>(context: &Context, op_name: &str, verifier: F) -> Result<(), Error>
where
    F: Fn(OperationRef<'_, '_>) -> Result<(), VerificationError> + 'static,
{
    ensure_dynamic_operation(context, op_name)?;

    let callbacks = MlirDynamicOpTraitCallbacks {
        construct: None,
        destruct: Some(destruct_verifier::<F>),
        verifyTrait: Some(verify::<F>),
        verifyRegionTrait: Some(verify_region),
    };
    let user_data = Box::into_raw(Box::new(verifier)).cast::<c_void>();

    // SAFETY: `user_data` is a valid `Box<F>`, which the trait owns from now on
    // and releases through `destruct_verifier`. The callbacks match the types
    // they are called with.
    let trait_ = unsafe {
        mlirDynamicOpTraitCreate(
            TypeId::create(&VERIFIER_TRAIT_ID).to_raw(),
            callbacks,
            user_data,
        )
    };
    attach(context, op_name, trait_)
}

fn attach(context: &Context, op_name: &str, trait_: MlirDynamicOpTrait) -> Result<(), Error> {
    // SAFETY: The caller checked that `op_name` is a registered dynamic
    // operation. The trait's ownership moves to MLIR; if attaching fails, MLIR
    // destroys it.
    let attached =
        unsafe { mlirDynamicOpTraitAttach(trait_, string_ref(op_name), context.to_raw()) };

    if attached {
        Ok(())
    } else {
        Err(Error::TraitAlreadyAttached(op_name.into()))
    }
}

/// Checks that `op_name` is registered and belongs to an extensible dialect.
///
/// Attaching a dynamic trait to any other operation is undefined behavior in the C API, so the wrappers check this first.
pub fn ensure_dynamic_operation(context: &Context, op_name: &str) -> Result<(), Error> {
    if !context.is_registered_operation(op_name) {
        return Err(Error::UnregisteredOperation(op_name.into()));
    }

    let (dialect_name, _) = op_name.split_once('.').unwrap_or((op_name, ""));
    // SAFETY: The context is valid, and the dialect is only inspected when it
    // was found.
    let is_extensible = unsafe {
        let dialect = mlirContextGetOrLoadDialect(context.to_raw(), string_ref(dialect_name));
        !dialect.ptr.is_null() && mlirDialectIsAExtensibleDialect(dialect)
    };

    if is_extensible {
        Ok(())
    } else {
        Err(Error::NotDynamicOperation(op_name.into()))
    }
}

unsafe extern "C" fn verify<F>(
    operation: MlirOperation,
    user_data: *mut c_void,
) -> MlirLogicalResult
where
    F: Fn(OperationRef<'_, '_>) -> Result<(), VerificationError>,
{
    // SAFETY: `user_data` is the `Box<F>` created by `attach_verifier`, which
    // stays alive until `destruct_verifier`. MLIR passes a valid operation.
    let (verifier, operation) =
        unsafe { (&*user_data.cast::<F>(), OperationRef::from_raw(operation)) };

    match verifier(operation) {
        Ok(()) => SUCCESS,
        Err(error) => {
            let name = operation.name();
            let name = name.as_string_ref().as_str().unwrap_or("<invalid name>");
            emit_error(operation.location(), &format!("'{name}' op {error}"));
            FAILURE
        }
    }
}

/// Our verifiers never need to look into regions, so this always succeeds.
unsafe extern "C" fn verify_region(_: MlirOperation, _: *mut c_void) -> MlirLogicalResult {
    SUCCESS
}

unsafe extern "C" fn destruct_verifier<F>(user_data: *mut c_void) {
    // SAFETY: `user_data` is the `Box<F>` created by `attach_verifier`, and
    // MLIR calls this exactly once when it destroys the trait.
    drop(unsafe { Box::from_raw(user_data.cast::<F>()) });
}
